// Refreshes benchmarks/vendor/easy-tz from a checkout. See ./easy-tz/README.md.
//
// Usage: node vendor/update-easy-tz.ts [path/to/easy-tz]
//        (defaults to $EASY_TZ, then to a sibling checkout of this repo)
//
// The two dist files are copied verbatim. meta.json is derived, and that is the
// reason this script exists rather than a cp: three of the facts the benches
// report live in easy-tz's shared/, which is neither published nor part of the
// dist bundle, so vendoring the bundle alone would silently drop them.

import { execFileSync } from "node:child_process";
import { copyFile, mkdir, writeFile } from "node:fs/promises";
import { fileURLToPath, pathToFileURL } from "node:url";

const OUT = new URL("./easy-tz/", import.meta.url);
const REPO = "https://github.com/leeoniya/easy-tz";
const SUBDIR = "dist/07-baked-rules";

const arg = process.argv[2] ?? process.env["EASY_TZ"];
const root = arg === undefined ? new URL("../../../easy-tz/", import.meta.url) : pathToFileURL(arg + "/");
const rootPath = fileURLToPath(root);

function git(...args: string[]): string {
  return execFileSync("git", ["-C", rootPath, ...args], { encoding: "utf8" }).trim();
}

// Refuse to record a commit that does not describe what is being copied — a
// vendored file whose stated provenance is wrong is worse than one with none.
const dirty = git("status", "--porcelain", "--", SUBDIR);

if (dirty !== "") {
  throw new Error(`${rootPath}${SUBDIR} has uncommitted changes:\n${dirty}\nCommit or stash them first.`);
}

const commit = git("rev-parse", "HEAD");

await mkdir(OUT, { recursive: true });
await copyFile(new URL(`${SUBDIR}/index.mjs`, root), new URL("index.mjs", OUT));

// .d.ts -> .d.mts is the only edit made to either file. TypeScript's nodenext
// resolution pairs a relative "./index.mjs" import with "./index.d.mts" and will
// not look at "./index.d.ts", and a relative import is what lib/easy-tz.ts uses.
await copyFile(new URL(`${SUBDIR}/index.d.ts`, root), new URL("index.d.mts", OUT));

const [{ zones }, { classIdx }, { scheduleClasses, genMeta, YEAR_START }] = (await Promise.all([
  import(new URL("shared/zones.ts", root).href),
  import(new URL("shared/bakedSchedule.ts", root).href),
  import(new URL("shared/schedule.ts", root).href),
])) as any[];

// kind 2 is easy-tz's irregular (Ramadan-driven) schedule class, whose transition
// dates the baked step table only approximates. Read off the tables rather than
// hardcoded, so a re-bake that changes the set is picked up here.
const irregularZones = (zones as string[]).filter((_, i) => {
  const ci = classIdx[i];
  return ci != null && ci !== -1 && scheduleClasses[ci]?.kind === 2;
});

// No vendored-at timestamp: re-running against the same commit should produce
// byte-identical output, so that an empty diff means nothing changed rather than
// meaning the script was not run. Git already records when the file landed.
const meta = {
  _: `generated by benchmarks/vendor/update-easy-tz.ts -- do not edit`,
  source: { repo: REPO, path: SUBDIR, commit },
  // which host's ICU the tables were baked from, for the report headers
  tables: { host: genMeta.host, icu: genMeta.icu, generated: genMeta.generated },
  // first instant the baked schedule covers; earlier values use baked history
  yearStart: YEAR_START,
  irregularZones,
};

await writeFile(new URL("meta.json", OUT), JSON.stringify(meta, null, 2) + "\n");

// The sidecar and the bundle have to agree, and this is the drift that matters:
// a name here that the bundle no longer enumerates would quietly shrink the
// excluded-zone count in benchmarks/format.ts's report.
const bundle = (await import(new URL("index.mjs", OUT).href)) as {
  getTimeZones: (withAliases?: boolean) => { name: string }[];
};
const known = new Set(bundle.getTimeZones(true).map((z) => z.name));
const missing = irregularZones.filter((z) => !known.has(z));

if (missing.length > 0) {
  throw new Error(`irregular zones absent from the vendored bundle: ${missing.join(", ")}`);
}

console.log(`vendored ${SUBDIR} from ${REPO} @ ${commit.slice(0, 12)}`);
console.log(`  ${known.size} zones, ${irregularZones.length} irregular, tables from ${genMeta.host}`);
